INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('40683b5b-183a-49e6-a133-bbcbebdc6d8a', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "77debc8d-a700-4bd5-80d3-a4fe0bd2b947", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "054becc1-affa-4e95-87f7-580c5bb196cb", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "8b8a4dec-187e-495f-b703-07bb66e0aef4", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "8205bc1c-0672-4317-87da-cdb9f63fe6d5", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "f5329441-ab07-46c4-9e0e-2b38a2850f7d", "text": "Igaz", "isCorrect": true}, {"id": "e2af44da-1724-47b2-990c-538e6f8c954d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21406b82-86ec-4b62-b6bd-5bbab44fad46", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "0e6532bf-72ec-484e-b254-fb9c11cae3ec", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "02aeaf49-fd89-437f-8b78-ff65e54c63ab", "text": "Igaz", "isCorrect": true}, {"id": "ed31e480-1479-4143-8a0a-12d28c3fb2fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d72c6aba-ee63-4756-b566-461ccb4f317d", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8e370b58-7eec-405a-bc6b-c49b94666a82', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "2e675160-7cc3-4aef-850b-f85fdc8b30c4", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "9c00017a-f049-413b-8901-6ec98ce789fc", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "41c8ba91-1f4c-4b07-84ef-cda39ad288ad", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "8045c569-3878-4e94-ab6b-671803a9a8ac", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "7a31a126-7255-45a4-bde7-cc290c3820e4", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "c1922784-51d3-46e4-bf2e-f341b1a2c352", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "5dd13700-ec39-4813-bb10-f26a95278b71", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5df674e0-87c8-4fa6-a043-69169030f308", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "690e554d-4bb2-495a-97b8-cca412d6c860", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "04bf64f6-26e4-46f1-b5b6-6a2b63685978", "text": "Igaz", "isCorrect": true}, {"id": "8ef061c9-757a-45eb-94ea-0ed6f777d445", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c815efb1-5231-4e8a-a67e-e58c0372c6e6", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "f3077808-2ea0-44a6-b149-e934e769eed6", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('67050fd3-90b4-49ce-9dba-730885795b83', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8e9ecc75-3760-4123-8b89-83ccf96f1356", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "f4f63ab8-97ed-4625-8751-68244eb01e2a", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "35afd8f3-75c9-4a29-8b8e-a08f2e4c0521", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "25e86c05-77f0-430d-ba08-47f45c695ea1", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "5ec35707-0c44-47bc-815c-e62c25cce381", "text": "Igaz", "isCorrect": true}, {"id": "3bb50c08-292e-466b-b060-cc799b19afd4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f2880ed-a8a2-477f-b129-09f89c9fd570", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0d6e8863-011a-4eaa-b5c0-4d7bb467d9f9", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "2a962341-ef05-4f09-a299-11b7d339b028", "text": "Igaz", "isCorrect": true}, {"id": "6c71e349-c3c8-4522-8cbe-978dd2b31f11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41c517be-d11c-42df-9126-2f8135cc46d4", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c1eab21a-1697-44c2-a37c-1e8622c175f0', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "277c6376-345c-4008-96f3-5db5c8c1ae77", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "a6372977-cd32-4795-93ad-c0f837e99524", "text": "3/5", "isCorrect": true}, {"id": "2ae62f1f-e6a0-4991-baad-9ebcaeebe28d", "text": "12/20", "isCorrect": false}, {"id": "f0a24ede-c523-4f9e-9a46-ed7cf507cf31", "text": "7/9", "isCorrect": false}, {"id": "9b346f57-ec30-4ed0-a1f2-dff7c8d8b373", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "03d60242-d355-4e44-86d7-768a77b4f8ee", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "0ca1be80-c0ea-4e33-96d7-15e71892d603", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "1f7a7c06-131f-4bf3-8e38-eda8eacfb7f2", "text": "1/6", "isCorrect": false}, {"id": "bd337b2b-4eeb-4c3b-aeca-22d0cca28eb4", "text": "2/3", "isCorrect": false}, {"id": "d5056ce6-ec6d-44b6-9552-03987301c851", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "6b89cbd7-9811-4293-9d96-ece461ac05e2", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "c6d222de-48f3-4687-83d5-2fedd0b0ef97", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "460dc95a-9e67-4041-b203-d00148f16b82", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "8254745a-a207-4ce8-b72b-a85ea41b8944", "text": "Igaz", "isCorrect": true}, {"id": "8ebe96cf-7f98-4645-9ef5-b5ce61f0f9bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a5e54ca-a085-48f5-8620-3e5e839d1ba3", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "13d0c19f-5401-4072-988c-d1c3dfb6770c", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b2d3b672-563b-4d10-98a7-f3b8d4a620f6', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "85f080bf-484b-491a-824c-0b0ce5a87012", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "4e3c68f8-1d81-4c43-b3d5-130bbe2630c4", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "4c5ee6ce-a43c-4448-ade3-2774569aa945", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "dbe2fb90-34c1-483b-b919-41691c03a5db", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "29d53ccd-65fc-45c4-b897-6e9ec0cf7ac9", "text": "1/5", "isCorrect": false}, {"id": "6585c23c-4c9b-408c-a4a5-b36dae4bd9ec", "text": "1/2", "isCorrect": false}, {"id": "219b1de4-5dd4-454b-a99a-9e381f6ae19c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "984e61b0-4bd5-481d-b7a0-40784ecd5880", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "b0dc2da2-b454-458b-86f4-51344898c8da", "text": "Igaz", "isCorrect": true}, {"id": "db1675ad-8482-4463-8cbe-f269184037bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2db9e2cc-d3f0-4fad-abef-fd182f0ee37e", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "3c4412dc-8f64-4203-b00d-3731416b25fb", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "a6a76a0f-13da-4748-a8a9-01f63d132fac", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "9396e370-9907-4388-98a9-a32bc7090a55", "text": "Igaz", "isCorrect": true}, {"id": "5272e95d-f3ff-4ad5-92f1-5de62562a471", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f7f313b8-23af-4109-bb3d-08e4581168ee', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b3d7d695-5756-4cc0-b457-5326c0ed309c", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "f9dfcb0a-94e7-485b-a52f-d862f56e519e", "text": "1/3", "isCorrect": true}, {"id": "97b72d61-5607-4527-89d2-bdbfe0ebb908", "text": "1/4", "isCorrect": false}, {"id": "d26bc62a-6560-456f-8c13-50115bcb37e5", "text": "2/3", "isCorrect": false}, {"id": "0aa08c00-6edb-47fe-af00-8769aee3030b", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "b579d566-23cb-404a-9066-9d7a15135169", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "9422f945-1f41-42a9-ad7a-40c04db88404", "text": "1/4", "isCorrect": true}, {"id": "1aab0c35-ce87-40ce-b465-a84ffa2af66a", "text": "1/5", "isCorrect": false}, {"id": "b077b4fe-3cc8-431e-84a8-424c488554fc", "text": "2/5", "isCorrect": false}, {"id": "a2e06aa3-9c4a-48d1-ab90-770474312314", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "82d7afd2-0888-492b-92b4-214f2a03271d", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "13709d29-410d-426e-9630-5f30fb9d29fc", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "31106d1e-7ed0-4d1f-bb23-37ac764dad2b", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "1ed66007-d8aa-4996-a089-d252f4150400", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "ce267357-a949-45f1-bb01-c9a8276d2233", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "65363c71-84b7-44fe-a3e2-627def78bdf4", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "e4e7a379-b0e0-45fd-be51-bc69c79346d9", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "2bd4f339-ac14-48e2-9301-b43cb6b03d23", "text": "Igaz", "isCorrect": true}, {"id": "50e8e2d8-cfdb-4865-9958-b1663acc9d5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dd85ccce-285b-4f67-b715-ef1315b44a1f', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "062c4287-1e9e-42ba-ba27-4f5f3a362a91", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "3b3ce691-4214-4e35-9f9b-0f24727756f0", "text": "5/6", "isCorrect": true}, {"id": "a2b89cd5-749a-4f2b-b661-0371c3e9a4a4", "text": "3/9", "isCorrect": false}, {"id": "dfdb67db-bc93-46f3-9020-52659f0ed22d", "text": "3/6", "isCorrect": false}, {"id": "b61055d3-da67-416a-b499-3d797e4b9bcd", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "3a738c2f-74af-41e7-bd16-f01b0576c44d", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "55c06f96-abe0-4bd6-83cf-ac8a5f129fbe", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "b61992fc-8425-404b-898f-72f3a9b1841f", "text": "8/11", "isCorrect": false}, {"id": "74e50d7d-fa55-4530-b79c-644cfe23c511", "text": "15/11", "isCorrect": false}, {"id": "bb844c08-b867-477d-8f81-63629e0a2f0d", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "33e8b950-d067-4c08-a0fb-da73df64830a", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "f8a30cc3-bc24-477b-b42e-bc9348cc7bc6", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "c106a3f8-7103-484e-acae-dfb6a7fc50f8", "text": "3/8", "isCorrect": false}, {"id": "603e33a5-0964-410f-9577-37abf03dbee0", "text": "1/4", "isCorrect": false}, {"id": "d35e3af8-6f59-43a9-8c63-238bda1da65b", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "bfdc77dc-b77f-41ad-a14f-180e269d6dff", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "cf7de230-7f6d-46d0-98d9-373345c01b44", "text": "9/4", "isCorrect": true}, {"id": "44376c88-801a-49f3-b933-5a237dc34551", "text": "-4/9", "isCorrect": false}, {"id": "cea87919-77c9-466d-a724-13ee3cf31530", "text": "1/4", "isCorrect": false}, {"id": "92cc2b35-4199-484d-9e84-eaa143434b19", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "5686637a-0006-4601-87c1-f19e545bf41b", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "7307a5d6-ffad-4f13-a425-e44222af50de", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "d94e39fe-e9b8-45db-916a-9e07a7630fb9", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "31e3f815-cbb0-4489-af26-af01c5211960", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "4682b51e-39a3-48c8-ae93-48351598db4d", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "1ac2961a-2808-4421-823c-7051f334bdbe", "text": "Igaz", "isCorrect": true}, {"id": "7d823ac4-2c3a-4617-8321-48ed7ee08955", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9adbeaa8-616d-496a-9305-2e2fc97bf934", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d021f628-04a1-435e-b4f7-6c518cf5d8bb', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "025197ce-1383-4c38-a689-a88d5b4ad864", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "0dadc499-3da5-4475-a671-359f5c1a2b6a", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "9b693763-628f-4bae-a1cd-be56456204a7", "text": "A számlálók leírása", "isCorrect": false}, {"id": "50b3df95-3e0f-4ee6-bd56-bb4d8e570197", "text": "A zárójel használata", "isCorrect": false}, {"id": "6d2cda92-4729-43f0-9e9c-0163a0ded730", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "a6342e5c-0167-4f2c-87f7-4995ca92db5f", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "289e5631-50fb-49eb-9fbc-8424e6fe3555", "text": "Igaz", "isCorrect": true}, {"id": "866a8fde-37dd-4509-a07f-012e4f41bfd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bb53d41-635f-4cff-ba48-1ccfef22f91b", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "f879a931-2c31-44c7-bb0a-0714aed5f11b", "text": "2/5", "isCorrect": true}, {"id": "f14bad91-fb0c-4a37-9a74-750c48ccccef", "text": "4/10", "isCorrect": false}, {"id": "284a5c72-f090-44db-aeb6-3887c1330a8a", "text": "1/5", "isCorrect": false}, {"id": "dc0816ca-ed35-49ad-950e-563be71584a0", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "32fc1562-8aa0-45ee-af30-573cfff4cae8", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "8c17227f-ecae-4e43-a2aa-511a9c880c6b", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "faccfb71-7065-45d6-b5f6-0be41bf9bb2c", "text": "Igaz", "isCorrect": true}, {"id": "5ff64f1f-e78f-4364-b63f-48d138b8dc9a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c3677b4a-b2a6-4131-90c0-23be348b162b", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f9d1e18f-0afa-494b-8fa7-17acd8dcbf61", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7549ed5e-2b76-46b2-a19d-0e4b8d339a05', '21feff02-016d-46e2-bb9d-c27495133b1b', '48. óra: Síkbeli alakzatok', 'Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "236d861a-8df4-4473-981b-95e5f9865fd5", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "f9e1aa26-8458-4ccf-96e1-713b8d726dea", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "b160d479-a133-4c26-86b3-14df61ded1b3", "text": "Hegyesszög", "isCorrect": true}, {"id": "f0c33c99-bc60-476d-8eec-a44583f216d6", "text": "Derékszög", "isCorrect": false}, {"id": "def9203e-0425-41c6-a0d6-9db241863b3a", "text": "Tompaszög", "isCorrect": false}, {"id": "57cbdc2c-8aea-4bc8-857f-967a521e3e9a", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "3d201eae-0fab-4876-84b8-2ed0b6949df3", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "f39271c6-29b7-4775-8c38-7780cf4d762b", "text": "Derékszög", "isCorrect": true}, {"id": "968431ab-d47b-4786-8a51-327e1d8d1caf", "text": "Hegyesszög", "isCorrect": false}, {"id": "2a8e3a2c-83c7-41b4-90f1-fa24a323d966", "text": "Tompaszög", "isCorrect": false}, {"id": "21b3ae24-c674-47ac-849c-7ca833b9e577", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "f8ddb3f1-05e7-40f7-b35a-fd5d88c1b050", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "15cf985d-cfc1-40ea-9140-29b61fb6e72e", "text": "Tompaszög", "isCorrect": true}, {"id": "04879d6a-6e8f-427a-8778-0c0e7be55226", "text": "Hegyesszög", "isCorrect": false}, {"id": "d20162d8-dbef-423a-af78-e516a59d25f7", "text": "Derékszög", "isCorrect": false}, {"id": "ace9e8c0-d03d-4a67-a331-60e661a09ffa", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "a05f6928-79e1-4bc5-8b38-88c508d42efd", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "b14d6563-8dbc-4f4b-90ce-a17be24b54ac", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "491baeb5-0cba-4ca6-b792-342fab532ab0", "text": "Igaz", "isCorrect": true}, {"id": "75e61dae-8b1f-4e24-b35f-822306ab753d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18bb0007-0ecf-4f6e-af3d-8090ec2c5d62", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "9e393ddf-3daf-4e5f-924e-a6677a84655a", "text": "Igaz", "isCorrect": true}, {"id": "3791cc0e-4beb-44ba-b89f-b36615693d3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('723968c1-532c-4947-b4ab-a3ca5010373f', '21feff02-016d-46e2-bb9d-c27495133b1b', '49. óra: Síkbeli alakzatok II.', 'Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "893b05d0-e324-4e61-bff5-dba61fa5eb4d", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "b3398b90-4763-4f10-98a1-99ecc540ebbb", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "bf16033e-1113-4ed0-b34c-da848adc397d", "text": "Négyzet", "isCorrect": true}, {"id": "2f498d91-2ca3-4f09-b778-f05cbed151cb", "text": "Rombusz", "isCorrect": false}, {"id": "2f58b1c8-fcb2-4b80-8544-8d9fb97bd01a", "text": "Téglalap", "isCorrect": false}, {"id": "0b4e8098-da70-4526-a388-d8f889c4477b", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "5b85813c-2088-41b5-a19e-02d960fa2cc3", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "9b70f1e1-2d4f-4b36-8e8a-3037db7caa7a", "text": "Rombusz", "isCorrect": true}, {"id": "7f83ca87-f7f5-4001-86c5-3b178d3eb0c8", "text": "Téglalap", "isCorrect": false}, {"id": "aa5e1500-12a6-48ac-a450-acbd8fdd1b52", "text": "Trapéz", "isCorrect": false}, {"id": "69b3626f-680a-4a9a-a08f-d2be70be6908", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "37f391b7-eddd-4ce5-9e16-1dd004a54256", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "32943b17-f49c-40cd-850b-fa8668387a43", "text": "Igaz", "isCorrect": true}, {"id": "52ae5212-b8bc-43a2-b76c-84fe81e0232b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ef479c4-110d-435d-82a3-8d55239a5fc5", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "3df91cc8-d9f8-4e87-bb33-ae2b6ed690d9", "text": "Igaz", "isCorrect": true}, {"id": "686de8af-3897-47dd-bbb8-31b48e9e0fd6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8598ba5e-beb4-4b33-a4b4-92c8f9fd2c70", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "f1a6d4e3-8c44-4c59-ae8e-c5f8d56d0998", "text": "Igaz", "isCorrect": true}, {"id": "121f67b8-ecf5-4ae4-8df7-aeaaabe736c8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "202d2a3b-703c-4159-a04c-73ef255633c6", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());